# use simple backtrack
solution=None

def backtrack(col, used_rows, perm):
    global solution
    if solution is not None:
        return
    if col==n:
        solution=perm.copy()
        return
    for r in range(n):
        if r in used_rows:
            continue
        # check partial Costas condition with previous columns
        ok=True
        for c_prev in range(col):
            dr=r-perm[c_prev]
            dc=col-c_prev
            # need to ensure no same (dr,dc) with earlier pairs
            for c2 in range(c_prev):
                if (perm[c_prev]-perm[c2], c_prev-c2)==(dr,dc):
                    ok=False;break
            if not ok:
                break
        if not ok:
            continue
        perm.append(r)
        used_rows.add(r)
        backtrack(col+1, used_rows, perm)
        used_rows.remove(r)
        perm.pop()

