def find():
    n=7
    length=2*n
    seq=[0]*length
    def backtrack(v):
        if v>n:
            return seq.copy()
        for i in range(length):
            j=i+v+1
            if j<length and seq[i]==0 and seq[j]==0:
                seq[i]=seq[j]=v
                res=backtrack(v+1)
                if res:
                    return res
                seq[i]=seq[j]=0
        return None
    return backtrack(1)

