import itertools, random
n=10
# try random graphs with degree 2-3 and girth>=5
def girth(edges):
    # BFS from each node to find shortest cycle
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v);adj[v].add(u)
    best=10**9
    for start in range(n):
        # BFS with parent
        from collections import deque
        dist=[-1]*n; parent=[-1]*n
        dist[start]=0
        q=deque([start])
        while q:
            u=q.popleft()
            for w in adj[u]:
                if dist[w]==-1:
                    dist[w]=dist[u]+1
                    parent[w]=u
                    q.append(w)
                elif parent[u]!=w: # found cycle
                    cycle_len=dist[u]+dist[w]+1
                    if cycle_len<best:
                        best=cycle_len
        if best==3:
            break
    return best if best!=10**9 else None

def degrees_ok(edges):
    deg=[0]*n
    for u,v in edges:
        deg[u]+=1;deg[v]+=1
    return all(2<=d<=3 for d in deg)

